export function parseHistory(text:string){let v;try{v=JSON.parse(text)}catch{throw Error('JSON 格式有误。')}return validateHistory(v)}
export function serializeHistory(c:HistoryConfig){return JSON.stringify(validateHistory(c),null,2)}
export function effectiveHistoryTracks(c:HistoryConfig){
 const derived:Track[]=[];
 if(c.recipeId==='dropdown'){
  const panel=c.tracks.find(track=>track.part==='panel'&&track.property==='opacity')!;
  // The chevron shares the panel's saved progress/timing. Legacy JSON needs no new field.
  derived.push({...panel,part:'chevron',property:'rotate',values:panel.values.map(value=>Number(value)*180)});
 }
 if(c.recipeId==='folder'){
  const paper=c.tracks.find(t=>t.part==='paper'&&t.property==='y')!,rotation=c.tracks.find(t=>t.part==='paper'&&t.property==='rotateX')!;
  for(let layer=1;layer<=3;layer++){
   const part=layer===1?'paper':'paper'+layer,delay=(layer-1)*32/c.durationMs,start=Math.min(.999,paper.start+delay),span=Math.max(.001,Math.min(paper.span,1-start));
   if(layer>1){derived.push({...paper,part,start,span,values:paper.values.map(v=>Number(v)<0?Number(v)*(layer===2?16:26)/7:Number(v))});derived.push({...rotation,part,start,span})}
   derived.push({...paper,part,start,span,property:'scale',values:paper.times.map(time=>.98-time*(layer-1)*.02)});
   derived.push({...paper,part,start,span,property:'z',values:paper.times.map(()=>-layer)});
  }
  const front=c.tracks.find(t=>t.part==='front'&&t.property==='rotateX')!;
  derived.push({...front,property:'boxShadow',values:front.times.map(time=>time<.5?'0px 8px 20px #2222220e':'0px 14px 30px #2222221a')});
 }
 return [...c.tracks.filter(track=>c.recipeId!=='dropdown'||track.part!=='item2'),...derived,t('root','x',[0,c.offsetX]),t('root','y',[0,c.offsetY]),t('root','scale',[['mini-sidebar','folder','dots','finger-tap','typewriter','yin-yang','pulse'].includes(c.recipeId)?c.scale:1,c.scale])];
}
export const textRiseCycle={fadeRatio:.35,fadeEase:[.42,0,.58,1]};
export function compiledTracks(c:HistoryConfig,reverse=false){
 const durationMs=c.recipeId==='glyph-wall'?glyphPlaybackMs(c.durationMs,c.wall??defaultGlyphWall,c.loop):c.durationMs;
 const reveal=c.recipeId==='text-rise',tracks=effectiveHistoryTracks(c);
 if(reveal&&!tracks.some(track=>track.part==='root'&&track.property==='opacity'))tracks.push(t('root','opacity',[1,1]));
 // A reveal exits by fading in place. Its letters never run their rise tracks backwards.
 if(reveal&&reverse){const opacity=tracks.find(track=>track.part==='root'&&track.property==='opacity')!;return [{target:'[data-part="root"]',property:'opacity',values:[opacity.values.at(-1)!,0],transition:{type:'tween' as const,duration:c.durationMs*textRiseCycle.fadeRatio/1000,delay:0,ease:motionEasing(textRiseCycle.fadeEase),times:[0,1],repeat:0,repeatDelay:0}}]}
 const all=tracks;return all.map(track=>{const springGlider=c.recipeId==='glass-radio'&&c.glass?.motion==='spring'&&track.part==='glider'&&track.property==='x';return {target:`[data-part="${track.part}"]`,property:track.property,values:reverse?[...track.values].reverse():[...track.values],transition:{type:springGlider?'spring' as const:'tween' as const,...(springGlider?{bounce:c.glass!.bounce,velocity:0}:{}),duration:durationMs*track.span/1000,delay:c.delayMs/1000+(reverse?Math.max(0,1-track.start-track.span):track.start)*durationMs/1000,ease:springGlider?undefined:motionEasing(['tideTime','watercolorTime'].includes(track.property)?L:c.recipeId==='glass-radio'&&['opacity','color'].includes(track.property)?glassRadioInteraction.appearanceEase:c.easing),times:reverse?track.times.map(n=>1-n).reverse():[...track.times],repeat:c.loop&&!reverse&&!['hover-invert','text-rise'].includes(c.recipeId)?Infinity:0,repeatDelay:c.loop&&!reverse&&!reveal?durationMs*(1-track.span)/1000:0}}})}
const names:Record<string,string>={watercolorTime:'水彩时钟',tideTime:'海浪时钟',glyphPhase:'解码周期进度',z:'三维深度',x:'横向位移',y:'纵向位移',scale:'缩放',scaleX:'横向缩放',scaleY:'纵向缩放',rotate:'旋转角度',rotateX:'X 轴翻转',opacity:'不透明度',width:'宽度',height:'高度',left:'横向位置',top:'纵向位置',borderRadius:'圆角',backgroundColor:'背景色',color:'文字颜色',boxShadow:'阴影',clipPath:'裁切',filter:'滤镜',textProgress:'字符归位进度',asciiPhase:'波形相位'};
const partLabels:Record<string,string>={wall:'字符墙',glider:'选择滑块',finish0:'银色表面',finish1:'金色表面',finish2:'铂金表面',label0:'Silver 文字',label1:'Gold 文字',label2:'Platinum 文字',machine:'打字机整体',carriage:'字车',trigger:'菜单触发器',root:'整体',face:'主体',panel:'面板',shade:'遮罩',chevron:'展开箭头',track:'开关轨道',knob:'滑块',label:'按钮文字',loader:'加载图标',check:'成功标记',directory:'目录',detail:'详情内容',divider:'内部竖线',surface:'共享表面',summary:'摘要',paper:'前层纸张',paper2:'中层纸张',paper3:'后层纸张',front:'文件夹封面',scramble:'字符',ascii:'字符画',image:'图形',fill:'进度条',halo:'光环',ball:'小球',finger:'手指',ring:'波纹',cursor:'指针',window:'窗口',watch:'手表',lock:'锁定图标',unlock:'解锁图标',fingers:'三指',file:'文件',corner:'触发角',upload:'上传区域',screen:'屏幕',sleep:'息屏标记'};
const partLabel=(selector:string)=>{const part=selector.match(/"([^"]+)"/)?.[1]??selector;const indexed=part.match(/^(item|char|line|page|dot|bar|finger|key|p)(\d+)$/);return indexed?`${({item:'项目',char:'字符',line:'横线',page:'页面',dot:'圆点',bar:'波柱',finger:'手指',key:'按键',p:'点'} as Record<string,string>)[indexed[1]]} ${Number(indexed[2])+1}`:partLabels[part]??part};
function asciiDescription(a:Readonly<AsciiSettings>){return `字符 ${JSON.stringify(a.characters)}；字符不透明度系数 ${Number((a.opacity*100).toFixed(2))}%；字号 ${a.fontSize} px；字符密度 ${Number((a.density*100).toFixed(2))}%；时钟倍率 ${a.speed}×；流场旋转角度 ${a.direction}°；扭曲 ${a.twist}；波形紧密度 ${a.tension}；颜色 ${a.color}；指针扰动强度 ${a.pointerStrength}×，影响半径 ${a.pointerRadius} px。`}
export function historyDescription(c:HistoryConfig){if(c.recipeId==='ascii-sharks')return asciiSharksDescription(c);if(c.recipeId==='coffee-selector')return coffeeDescription(c);if(isStudioEffect(c.recipeId))return studioDescription(c);if(isAceternityEffect(c.recipeId))return aceternityDescription(c);if(c.recipeId==='rounded-checks')return checksDescription(c);if(c.recipeId==='glass-folder')return glassFolderDescription(c);if(c.recipeId==='scroll-progress')return scrollProgressDescription(c);if(c.recipeId==='hook-sidebar')return hookDescription(c);if(c.recipeId==='rail-toc')return railDescription(c);if(c.recipeId==='duration-picker')return durationDescription(c);if(c.recipeId==='album-rail')return albumDescription(c);if(c.recipeId==='hover-preview')return hoverPreviewDescription(c);if(c.recipeId==='orbit-reel')return orbitDescription(c);if(isReelRecipe(c.recipeId))return reelDescription(c);if(isWatercolorRecipe(c.recipeId))return watercolorDescription(c);if(c.recipeId==='particle-tide')return tideDescription(c);const r=recipeMap[c.recipeId],tracks=compiledTracks(c);return {title:r.label,summary:`${r.label} · ${c.durationMs} ms · ${r.source}`,sections:[{label:'组件',text:`${r.label}（${effectTerms[r.id]?.english??r.id}；${r.id}）`},{label:'触发方式',text:triggerDescription(c.recipeId)+(c.recipeId==='glyph-wall'?' 详情中自动扫描，播放按钮暂停或接续当前阶段。词组聚焦时冻结扫描，点击空白或重排按钮开始一轮新排布。':c.recipeId==='glass-radio'?' 工具栏依次演示 Silver → Gold → Platinum → Silver；暂停保持进度，继续从暂停处接续。':c.recipeId==='text-rise'?' 详情页播放按钮演示逐字上移揭示、原位淡出、不可见时复位；开启循环后从头继续，暂停与继续保留当前阶段进度。':c.recipeId==='text-scramble'?' 播放按钮复位后，在调整前后相同位置演示一次局部扰动。':c.recipeId==='ascii-wave'?' 详情页自动流动；暂停冻结累计相位，继续接续当前进度，不演示反向返回。':effectTrigger(c.recipeId)==='loading'?' 详情页自动按配置播放完整周期；暂停保持当前画面，继续从同一进度接续，不反向返回。':' 详情页播放按钮同步演示两侧：普通动效从初态进入终态，再返回初态一次；加载类按循环配置持续播放。暂停保留当前画面，继续时从暂停进度接续。')},{label:'起点与终点',text:c.recipeId==='mini-sidebar'?`单层用途分类；横线从收拢态平滑伸出，最大长度 ${c.tracks.find(t=>t.part==='line2'&&t.property==='width')!.values.at(-1)} px。整体缩放 ${Math.round(c.scale*100)}%，在初态和展开时一致；横线、间距和标签同步缩放。`:c.recipeId==='glass-radio'?'初态为 Silver，Gold 与 Platinum 分别位于滑块自身宽度的 100% 和 200%。选中项保持清晰文字与对应的金属表面；导出基础轨道表示 Silver → Gold，交互适配器将同一配置映射为任意两项之间的切换。':tracks.map(t=>`${partLabel(t.target)}的${names[t.property]??t.property}：${t.values[0]} → ${t.values.at(-1)}${t.values.length>2?'（含 '+t.values.length+' 个关键帧）':''}`).join('；')+'。'},{label:'时序',text:c.recipeId==='glyph-wall'?`扫描 ${c.durationMs} ms，停留 ${c.wall!.holdMs} ms，消散 ${c.durationMs*.25} ms，轮间停顿 ${c.wall!.restMs} ms；${c.loop?'整轮 '+glyphCycleMs(c.durationMs,c.wall!)+' ms。':'关闭循环后在扫描结束时保留完整词组。'} 初始延迟 ${c.delayMs} ms。`:c.recipeId==='glass-radio'?`滑块切换 ${c.durationMs} ms，触发延迟 ${c.delayMs} ms，${c.glass?.motion==='spring'?`弹簧动画（Spring），回弹系数 Bounce ${c.glass.bounce}；时长控制节奏，不代表精确落稳时间`:easingDescription(c.easing)}。配色过渡 ${Number((c.durationMs*c.tracks.find(t=>t.part==='finish0')!.span).toFixed(3))} ms，文字变色 ${Number((c.durationMs*c.tracks.find(t=>t.part==='label0')!.span).toFixed(3))} ms，均使用 ease-in-out。`:c.recipeId==='text-rise'?`揭示阶段 ${c.durationMs} ms，触发延迟 ${c.delayMs} ms，${easingDescription(c.easing)}。随后原位淡出 ${Number((c.durationMs*textRiseCycle.fadeRatio).toFixed(3))} ms，使用柔和缓入缓出；一轮共 ${Number((c.delayMs+c.durationMs*(1+textRiseCycle.fadeRatio)).toFixed(3))} ms。`:c.recipeId==='mini-sidebar'?`演示与收回时长 ${c.durationMs} ms，触发延迟 ${c.delayMs} ms，${easingDescription(c.easing)}。悬停伸展使用固定响应的解析临界阻尼弹簧；时长与曲线用于演示轨道和移开收回。`:`总时长 ${c.durationMs} ms，统一触发延迟 ${c.delayMs} ms，${easingDescription(c.easing)}。各轨道按配置中的 start / span 和 times 分阶段运行。`},{label:'进入与退出',text:(c.recipeId==='glyph-wall'?'扫描带经过网格时，词组按所在位置逐字解码；完整呈现后停留，再消散回噪声。词组聚焦时清除附近噪声、压暗其余词组并保持当前时钟。':c.recipeId==='glass-radio'?'选择新选项时，滑块移动到对应分段，金属渐变与高光交叉过渡；完成后保持当前选项，重复选择同一项不重播。':c.recipeId==='yin-yang'?'太极图匀速旋转，两颗圆点同步放大后缩回，悬停时阴影在 300ms 内加深。暂停保留旋转角度和圆点缩放，继续时接续同一周期。':c.recipeId==='typewriter'?'按键依次敲击，纸张分段上移；一轮末尾字车回位，纸张复位，机身轻微弹跳。暂停保留所有部件的当前进度，继续时接续同一周期。':c.recipeId==='finger-tap'?'四指在同一周期内错峰敲击，手掌和拇指保持不动。暂停保留当前角度，再次播放接续当前周期。':c.recipeId==='progress'?'详情页自动正向填充；工具栏暂停时保持当前进度，继续时接续同一轮，不反向回退。':c.recipeId==='mini-sidebar'?'初态显示各用途分类的短线。进入导航区域后，附近横线按距离伸长并显示名称；点击直接选中分类。移开时平滑收回横线并淡出名称，保留当前选择。':c.recipeId==='ascii-wave'?'进入字符画区域后按流场运行，离开冻结当前相位并清除指针扰动。':c.recipeId==='text-rise'?'文字按错峰时序从下向上揭示。全部到位后保持位置不动，以揭示时长的 35% 平滑淡出至不透明度 0；完全不可见后才在遮罩下方复位，不反向下移。':c.recipeId==='text-scramble'?'仅指针附近字符出现扰动，文字不移动；停住或离开后，已触及字符按各自恢复进度归位。':['stagger','text-rise'].includes(c.recipeId)?'点击后从初态正向揭示，完成后保留终态；再次点击复位后重新揭示。':effectTrigger(c.recipeId)==='loading'?'按关键帧正向运行完整周期；暂停保持当前画面，继续接续，不执行反向退出。':'进入按关键帧正向运行，退出将关键帧、阶段顺序与时间点反转。')+(c.recipeId==='glyph-wall'?(c.loop?'按配置重复整轮；每轮是否重排由设置决定。':'只解码一次，保留可读词组。'):c.recipeId==='glass-radio'?'选择状态不会自动循环。':c.recipeId==='yin-yang'?(c.loop?'持续重复完整旋转与呼吸周期。':'完成一周后停止。'):c.recipeId==='typewriter'?(c.loop?'持续重复完整打字周期。':'完成一轮后保持初始位置。'):c.recipeId==='finger-tap'?(c.loop?'按配置持续重复整个敲击周期。':'完成一个周期后保持静止。'):c.recipeId==='progress'?(c.loop?'到达目标进度后立即回到起始进度，继续正向填充。':'单轮结束后保持目标进度。'):c.recipeId==='ascii-wave'?(c.loop?'区域内持续流动。':'完成一段流动后保留画面。'):c.recipeId==='text-rise'?(c.loop?'淡出后重新逐字上移揭示，按整轮持续循环。':'淡出后结束本次演示。'):c.recipeId==='text-scramble'?'未触及字符始终可读；不会自动逐字揭示整行。':['stagger','text-rise'].includes(c.recipeId)?(c.loop?'按配置持续重复。':'不自动重复。'):effectTrigger(c.recipeId)==='loading'?(c.loop?'按完整正向周期无限循环；工具栏暂停不改变循环设置。':'完成一轮后停止，不反向返回。'):c.loop?'进入后无限循环；再次操作停止循环并反向返回初态。':'完成后保留终态，不自动重复。')},{label:'重复操作与打断',text:c.recipeId==='glyph-wall'?'暂停保持当前相位、噪声和解码进度，继续时接续。词组悬停和键盘聚焦保持时钟；离开或失焦继续。点击空白重新排布并从头扫描；参数更改从新配置初态重播，不排队。随机种子、聚焦和观察倍速不写入配置。':c.recipeId==='glass-radio'?'使用原生单选按钮，支持 Tab、方向键与空格；每个预览实例使用独立的名称和 ID。选择与焦点属于临时交互状态，不写入 JSON。'+(c.interruption==='retarget'?'快速切换停止旧轨迹，从当前画面转向最新目标，不排队。':'快速切换停止旧轨迹，复位到上一选项的起点后开始新过渡，不排队。')+'工具栏暂停冻结当前时钟，继续保留进度。':c.recipeId==='text-rise'?'一次新演示先在不可见时复位，再逐字向上揭示；淡出阶段只改变不透明度。暂停保留字符位置、透明度与阶段进度，继续时接续，不排队。':c.recipeId==='progress'?'详情页工具栏暂停并保留当前进度，再次播放从暂停处继续；新演示和修改参数时从配置起始进度重新填充。循环不把当前中间值作为下一轮起点，不排队。':c.recipeId==='mini-sidebar'?'指针位置、焦点和当前项为临时交互状态，不写入配置。点击直接切换分类；方向键和 Home/End 在同一层移动焦点。横线使用持续时钟跟随指针，换方向时保留当前速度。移开、焦点移出或按 Escape 后保留当前项，标签在原来的位置淡出，横线从当前长度平滑收回；退出始终接续当前画面，不排队。':c.recipeId==='ascii-wave'?'再次进入区域或点击播放按钮，从配置的初始相位重新开始；在区域内修改流场参数时保留当前相位，不排队。循环回绕通过累计相位保持连续。':c.recipeId==='text-scramble'?'移动指针只刷新命中字符的恢复轨迹；已离开的字符独立恢复，不影响其他文字。指针位置、局部进度与字符序列为临时状态，不写入 JSON；播放按钮每次清空旧轨迹，演示相同位置。':['stagger','text-rise'].includes(c.recipeId)?'点击组件或播放按钮每次复位，从配置初态重新揭示；不排队。':effectTrigger(c.recipeId)==='loading'?'暂停保持当前周期进度，继续接续；修改参数时按新配置从完整周期起点重播，不排队。':c.interruption==='retarget'?'停止旧轨迹，保留当前画面作为新轨迹第一帧，转向最新目标；不排队。循环的新周期从本周期起点开始。':'停止旧轨迹，每条轨道开始时复位到该方向的起点后从头播放；不排队。'},{label:'减少动态效果',text:c.recipeId==='glyph-wall'?'遵循系统减少动态效果设置，直接显示完整词组；不扫描、不扰动、不循环。观察倍速不写入配置。':'遵循系统 prefers-reduced-motion，跳过延迟、循环和动画，直接呈现目标帧。观察倍速只修改 Motion 控制器 speed，不写入配置。'},{label:'轨道明细',text:tracks.map(t=>`${t.target} / ${names[t.property]}：延迟 ${Number((t.transition.delay*1000).toFixed(3))} ms，运行 ${Number((t.transition.duration*1000).toFixed(3))} ms，${t.values.length} 帧；时间点 [${t.transition.times.join(', ')}]；值 [${t.values.join(', ')}]`).join('\n')},...(c.recipeId==='ascii-wave'?[{label:'字符画设置',text:asciiDescription(c.ascii??defaultAsciiSettings)}]:[]),...(c.recipeId==='glyph-wall'?[{label:'文字墙设置',text:`词组 ${JSON.stringify(c.wall!.words)}；排布 ${c.wall!.layout}；方向 ${c.wall!.direction}；字符集 ${c.wall!.charset}；字号 ${c.wall!.fontSize}px；密度 ${c.wall!.density}；噪声基础不透明度 ${c.wall!.wallOpacity}；扰动 ${c.wall!.scrambleHz}Hz；逐字跨度 ${c.wall!.stagger}；扫描带半宽比例 ${c.wall!.bandWidth}；每轮重排 ${c.wall!.shuffle}；词组色 ${c.wall!.color}；噪声色 ${c.wall!.noiseColor}。`}]:[]),{label:'来源',text:`${r.source} · ${r.file}:${r.line}。${r.note??'复用该项目已使用的运动类型，缩小为独立教学示例。'} 业务布局尺寸、字体和图像使用此示例自己的内容。`}]}}
export function proceduralText(property:string,value:number):string{
 if(property==='textProgress'){const progress=Math.max(0,Math.min(1,value)),text='Thank you for playing my game',alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!<>-_/[{}]=+*^?#|';return Array.from(text).map((s,i)=>s===' '||progress>=(i+1)/text.length?s:alphabet[(Math.floor(progress*40)+i*3)%alphabet.length]).join('')}
 const chars=' cyslap';return Array.from({length:13},(_,y)=>Array.from({length:38},(_,x)=>{const n=Math.sin(x*.22+value)*Math.cos(y*.32-value*.7);return chars[Math.max(0,Math.min(chars.length-1,Math.floor((n+1)/2*chars.length)))]}).join('')).join('\n');
}
